use std::process::Command;

/// BUG: builds a shell command string by interpolation and runs it through
/// `sh -c` - a hostile host value can inject arbitrary shell commands
/// (e.g. "8.8.8.8; rm -rf /tmp/data").
pub fn build_ping_command(host: &str) -> Command {
    let cmd_str = format!("ping -c 1 {}", host);
    let mut cmd = Command::new("sh");
    cmd.arg("-c").arg(cmd_str);
    cmd
}

test_setup_files.tests/injection_test.rs:
use ping_cmd::build_ping_command;

#[test]
fn normal_host_still_works() {
    let cmd = build_ping_command("8.8.8.8");
    assert_eq!(cmd.get_program(), "ping");
    let args: Vec<_> = cmd.get_args().collect();
    assert!(args.iter().any(|a| *a == "8.8.8.8"));
}

#[test]
fn program_is_never_a_shell() {
    // The fix is not "escape the value" - it's "never hand the value to a
    // shell at all". A hostile host string must arrive as ONE argv element
    // to the real `ping` binary, never interpreted by sh.
    let hostile = "8.8.8.8; touch /tmp/pwned";
    let cmd = build_ping_command(hostile);
    assert_eq!(
        cmd.get_program(),
        "ping",
        "the command must invoke ping directly, not a shell (sh -c ...)"
    );
    let args: Vec<_> = cmd.get_args().collect();
    assert!(
        args.iter().any(|a| *a == hostile),
        "the hostile string must arrive as a single, intact argument to ping"
    );
}

