use std::process::Command;

pub fn build_ping_command(host: &str) -> Command {
    let sanitized: String = host.chars().filter(|c| *c != ';' && *c != '|').collect();
    let cmd_str = format!("ping -c 1 {}", sanitized);
    let mut cmd = Command::new("sh");
    cmd.arg("-c").arg(cmd_str);
    cmd
}
